 "content": "def transform(grid):
    n = len(grid)
    if n % 3 or any(len(row) != n for row in grid):
        raise ValueError('expected square grid with dimensions divisible by 3')
    out = []
    for br in range(0, n, 3):
        row = []
        for bc in range(0, n, 3):
            colors = {grid[r][c] for r in range(br, br + 3) for c in range(bc, bc + 3) if grid[r][c] not in (0, 5)}
            if len(colors) > 1:
                raise ValueError(f'ambiguous tile: {colors}')
            row.append(next(iter(colors), 0))
        out.append(row)
    return out

if __name__ == '__main__':
